package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

type SearchRequest struct {
	Category string `json:"category"`
	MinPrice float64 `json:"min_price"`
	MaxPrice float64 `json:"max_price"`
	SortBy   string `json:"sort_by"`
	Order    string `json:"order"`
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", 400)
		return
	}

	// Build query with parameterized values for price range
	query := "SELECT id, name, price, category FROM products WHERE 1=1"
	args := []interface{}{}
	argIdx := 1

	if req.Category != "" {
		query += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, req.Category)
		argIdx++
	}

	if req.MinPrice > 0 {
		query += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, req.MinPrice)
		argIdx++
	}

	if req.MaxPrice > 0 {
		query += fmt.Sprintf(" AND price <= $%d", argIdx)
		args = append(args, req.MaxPrice)
		argIdx++
	}

	// Sort handling - allowlist check
	allowedSorts := map[string]bool{"name": true, "price": true, "created_at": true}
	if req.SortBy != "" && allowedSorts[req.SortBy] {
		query += " ORDER BY " + req.SortBy
	} else if req.SortBy != "" {
		// Fallback: still use it but try to sanitize
		sanitized := strings.ReplaceAll(req.SortBy, ";", "")
		sanitized = strings.ReplaceAll(sanitized, "--", "")
		query += " ORDER BY " + sanitized
	}

	// Order direction
	if strings.EqualFold(req.Order, "desc") {
		query += " DESC"
	} else if strings.EqualFold(req.Order, "asc") {
		query += " ASC"
	} else if req.Order != "" {
		// User provided non-standard order value, append raw
		query += " " + req.Order
	}

	query += " LIMIT 50"

	rows, err := db.Query(query, args...)
	if err != nil {
		http.Error(w, "query error", 500)
		return
	}
	defer rows.Close()

	type Product struct {
		ID       int     `json:"id"`
		Name     string  `json:"name"`
		Price    float64 `json:"price"`
		Category string  `json:"category"`
	}

	var results []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category); err != nil {
			continue
		}
		results = append(results, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	http.ListenAndServe(":8080", nil)
}
